export interface Parcel {
  trackingId: string;
  destination: string;
  recipient: string;
}

function normalized(value: string, name: string): string {
  if (typeof value !== "string" || value.trim().length === 0) {
    throw new TypeError(`${name} must contain text`);
  }
  return value.trim().toLowerCase();
}

export class ParcelRegistry {
  private readonly parcels = new Map<string, Parcel>();

  addParcel(parcel: Parcel): void {
    if (typeof parcel !== "object" || parcel === null) {
      throw new TypeError("Invalid parcel");
    }
    normalized(parcel.trackingId, "trackingId");
    normalized(parcel.destination, "destination");
    normalized(parcel.recipient, "recipient");
    if (this.parcels.has(parcel.trackingId)) {
      throw new Error(`Duplicate tracking ID: ${parcel.trackingId}`);
    }
    this.parcels.set(parcel.trackingId, { ...parcel });
  }

  removeParcel(trackingId: string): void {
    normalized(trackingId, "trackingId");
    this.parcels.delete(trackingId);
  }

  searchDestination(destination: string): Parcel[] {
    const query = normalized(destination, "destination");
    return [...this.parcels.values()]
      .filter((parcel) => normalized(parcel.destination, "destination") === query)
      .map((parcel) => ({ ...parcel }));
  }

  searchRecipient(recipient: string): Parcel[] {
    const query = normalized(recipient, "recipient");
    return [...this.parcels.values()]
      .filter((parcel) => normalized(parcel.recipient, "recipient") === query)
      .map((parcel) => ({ ...parcel }));
  }
}
```

