import { Parcel, ParcelRegistry } from "./solution";

function assert(condition: boolean, message: string): void {
  if (!condition) throw new Error(message);
}

function expectError(action: () => void, ctor: typeof Error, message: string): void {
  let caught: unknown;
  try { action(); } catch (error) { caught = error; }
  assert(caught instanceof ctor, message);
}

const empty = new ParcelRegistry();
assert(empty.searchDestination("Bengaluru").length === 0, "empty destination search returns empty array");
assert(empty.searchRecipient("Forge").length === 0, "empty recipient search returns empty array");

const first: Parcel = { trackingId: "T-1", destination: "  Bengaluru ", recipient: " Navneet " };
const registry = new ParcelRegistry();
registry.addParcel(first);
registry.addParcel({ trackingId: "T-2", destination: "bengaluru", recipient: "Other" });
registry.addParcel({ trackingId: "T-3", destination: "Mumbai", recipient: "NAVNEET" });
first.destination = "Changed";
first.recipient = "Changed";

const byDestination = registry.searchDestination(" BENGALURU ");
assert(byDestination.length === 2 && byDestination[0].trackingId === "T-1" && byDestination[1].trackingId === "T-2", "destination search normalizes and preserves insertion order");
const byRecipient = registry.searchRecipient(" navneet ");
assert(byRecipient.length === 2 && byRecipient[0].trackingId === "T-1" && byRecipient[1].trackingId === "T-3", "recipient search normalizes and preserves insertion order");
byDestination[0].destination = "Corrupted";
assert(registry.searchDestination("bengaluru")[0].destination === "  Bengaluru ", "search results are fresh copies");
assert(registry.searchDestination("bengaluru")[0] !== registry.searchDestination("bengaluru")[0], "records are freshly copied on every search");

expectError(() => registry.addParcel({ trackingId: "T-1", destination: "X", recipient: "Y" }), Error, "duplicate tracking IDs throw Error");
expectError(() => registry.removeParcel("unknown"), Error, "removing unknown ID throws Error");
assert(registry.searchDestination("bengaluru").length === 2, "failed operations leave state unchanged");
registry.removeParcel("T-2");
assert(registry.searchDestination("bengaluru").length === 1, "known parcel is removed");

const malformed: unknown[] = [
  null,
  { trackingId: "", destination: "X", recipient: "Y" },
  { trackingId: "   ", destination: "X", recipient: "Y" },
  { trackingId: "T", destination: " ", recipient: "Y" },
  { trackingId: "T", destination: "X", recipient: "" },
  { trackingId: 3, destination: "X", recipient: "Y" }
];
for (const bad of malformed) {
  expectError(() => registry.addParcel(bad as Parcel), TypeError, "malformed parcels throw TypeError");
}
for (const bad of ["", "   ", null, 4]) {
  expectError(() => registry.removeParcel(bad as string), TypeError, "malformed removal argument throws TypeError");
  expectError(() => registry.searchDestination(bad as string), TypeError, "malformed destination query throws TypeError");
  expectError(() => registry.searchRecipient(bad as string), TypeError, "malformed recipient query throws TypeError");
}

